+  band: "APPROVED" | "DEGRADED" | "FAILED" | null;
+  /** Planned voices without a completed result, as `provider/model`. */
+  incomplete: string[];
+  /** completed < planned, or the band is DEGRADED or FAILED. */
+  degraded: boolean;
